"""Render the complete table results and method without selecting favorable cases."""
import json,csv,statistics
from pathlib import Path
r=Path(__file__).resolve().parents[1]
d=r/'results/windows-net10-capture-isolation-run5'
rows=json.loads((d/'summary.json').read_text(encoding='utf-8'))
table=[s for s in rows if s['case']!='micro']
assert len(table)==18
paired=[]
for case in sorted({s['case'] for s in table}):
    for pair in range(12):
        arms={}
        for arm in ['a','b']:
            records=[json.loads(l) for l in (d/f'{case}-pair{pair:02d}-{arm}.jsonl').read_text(encoding='utf-8-sig').splitlines()][1:]
            arms[arm]={op:statistics.median(x['elapsedNs'] for x in records if x['operation']==op) for op in {x['operation'] for x in records}}
        for op in sorted(arms['a']):
            paired.append(dict(case=case,pair=pair,operation=op,disabled_ms=arms['a'][op]/1e6,enabled_ms=arms['b'][op]/1e6,ratio=arms['b'][op]/arms['a'][op]))
with (d/'process-pairs.csv').open('w',newline='',encoding='utf-8') as f:
    writer=csv.DictWriter(f,fieldnames=list(paired[0]));writer.writeheader();writer.writerows(paired)
for zh in [False,True]:
    title='# CaptureUnmatchedValues 隔离 A/B 测试' if zh else '# Isolated CaptureUnmatchedValues A/B benchmark'
    intro=('两组均来自最终生产提交 `2b1cafd50978e1622b68c45aba7ca572506aa5d4`。A 为 `false`，B 为原来的 `true`，只切换 AntDomComponentBase 上一个布尔标记；字典合并、Razor、属性输入和渲染输出保持一致。B/A 大于 1 表示启用捕获更慢。生产分支和 PR 均未修改，也未向 issue/PR 发布消息。' if zh else 'Both arms use final production commit `2b1cafd50978e1622b68c45aba7ca572506aa5d4`. A disables the AntDomComponentBase capture flag; B retains the original enabled flag. This single Boolean is the only library source change. Merge code, Razor, parameter inputs and native output are the same. B/A > 1 means capture enabled is slower. The production branch and PR were not changed, and no issue/PR message was posted.')
    conclusion = ("默认 1 万格的三项点估计为 -2.39% 至 +0.41%，区间均跨零。默认 4 万格挂载 +1.41%、变更数据更新 -1.42%，区间跨零；同数据更新 +5.92% [95% CI +0.11%, +13.91%]，因此不能称完全无退化。显式 shared-only 的挂载/同数据/变更数据更新为 +0.60% / +1.52% / +3.33%；双字典为 +4.36% / +5.31% / +6.76%，这些区间全部跨零。表格分配量差异最多 696 B（进程中位数的中位数之差），没有与单元格数成比例的额外分配；全部 26 项合并微基准的每次调用分配量相同。" if zh else "For default 10k-cell tables, the three point estimates range from -2.39% to +0.41%, all intervals spanning zero. For default 40k-cell tables, mount is +1.41% and changed-data update -1.42% (intervals spanning zero), while same-data update is +5.92% [95% CI +0.11%, +13.91%]; zero regression is therefore not established. Explicit shared-only mount/same/changed estimates are +0.60% / +1.52% / +3.33%; both-dictionary estimates are +4.36% / +5.31% / +6.76%, all with intervals spanning zero. Table allocation differences are at most 696 B (difference of medians of process medians), without additional allocation proportional to cell count. All 26 helper cases have identical bytes/call.")
    tradeoff = ("取舍：保留 true 可以继续支持直接写 HTML 属性。当前证据未显示默认路径一致的大幅退化，显式单字典的点估计较小，但区间仍允许更大的成本；尤其 4 万格同数据更新提示实际退化的可能。基于这轮数据，保留便利性仍是合理选择，但不能把‘性能开销极小’当作已证实事实。没有实际捕获未知参数的测试，也不能承诺直接写 HTML 属性时总成本与本轮完全相同。小表对照和绕过参数分发的微基准也存在波动，不能把每项差异都归因于捕获算法。" if zh else "Tradeoff: retaining true preserves direct HTML-attribute syntax. This study does not show a consistent large slowdown on the default path, and explicit single-dictionary point estimates are modest, but the intervals still allow larger costs; the default 40k same-data update flags a possible real regression. Keeping the convenience remains a reasonable choice on this evidence, but extremely small overhead is not established. Actual capture of unknown parameters was not measured, so total cost of inline HTML attributes is not promised to equal this study. The small-table control and helper cases that bypass parameter dispatch also fluctuate; every difference must not be attributed to the capture algorithm.")
    lines=[title,'',intro,'',conclusion,'',tradeoff,'','## '+('全部表格结果' if zh else 'All table results'),'']
    lines+=['| Case | Operation | A false (ms) | B true (ms) | B/A change [95% CI] | Allocated bytes A → B |','|---|---|---:|---:|---:|---:|']
    for s in table:
        lines.append(f"| {s['case']} | {s['operation']} | {s['baseline_median_ns']/1e6:.3f} | {s['candidate_median_ns']/1e6:.3f} | {(s['paired_ratio']-1)*100:+.2f}% [{(s['ci95_low']-1)*100:+.2f}%, {(s['ci95_high']-1)*100:+.2f}%] | {s['baseline_median_bytes']:,.0f} → {s['candidate_median_bytes']:,.0f} |")
    method=('12 对独立进程/场景，AB/BA 平衡交替、场景顺序种子 4852；每进程 3 次预热、4 次采样。共 168 个正式进程、4224 条样本。先取每进程中位数，再对 12 对耗时比值取几何平均，进行 20000 次配对 bootstrap，给出 95% 区间。毫秒列为进程中位数的中位数，不是比值估计的分子分母，也不是配对绝对差估计；跨 0 的百分比区间不能证明零开销。未剔除离群值，未作多重比较校正。核心计时和分析与此前相同；本轮在计时外增加输出哈希校验，并增加 shared-only 用例，未与历史样本混合。' if zh else '12 independent paired processes per case, balanced alternating AB/BA, case shuffle seed 4852; 3 warmups and 4 samples/process. 168 formal processes and 4224 sample records. Take each process median, then the geometric mean of 12 paired time ratios, with 20000 paired bootstrap resamples and 95% intervals. Milliseconds are medians of process medians, not the numerator/denominator of the paired ratio estimator or a paired absolute-delta estimate. An interval spanning 0% does not prove zero overhead. No outlier removal or multiple-comparison adjustment. Core timing/analysis are unchanged; this run adds output validation outside timing and a shared-only case, without pooling historical samples.')
    fixtures=('none 不传 AdditionalAttributes（连 null 也不传）；legacy 仅传 OnCell；shared 显式传预先构造的四项 AdditionalAttributes；both 同时传同样的四项 AdditionalAttributes 和四项 OnCell（两键重叠）。每对 A/B 参数完全相同，字典在计时外创建，旧字典优先级不变。没有向组件传未知参数，因此测的是捕获标记对参数分发路径的影响，不包含实际收集未知 HTML 参数时创建字典的成本。26 个直接调用合并函数的微基准作为负对照；其代码不经过参数分发，波动不能归因于捕获开关。' if zh else 'none supplies no AdditionalAttributes parameter, even null; legacy supplies only OnCell; shared explicitly passes a prebuilt four-entry AdditionalAttributes dictionary; both supplies the same four-entry AdditionalAttributes plus four-entry OnCell dictionary (two overlapping keys). Each A/B pair receives identical parameters. Fixtures are built outside timing and legacy precedence is unchanged. No unknown component parameters are passed, so this measures the flag-selected parameter dispatch path, excluding dictionary creation when actually capturing unknown HTML parameters. The 26 direct helper microcases are a negative control, bypass parameter dispatch, and their fluctuations cannot be attributed to the capture flag.')
    validation=('所有 1728 条表格操作记录均完成单元格/表头校验；每对对应采样的原生输出 SHA256、批次数、组件更新数、编辑数相同。哈希保留原生元素树、属性名与标量值、文本/markup；跳过组件参数、框架 ID/引用捕获，事件委托用其类型表示，未比较委托身份或浏览器行为。构建日志仅替换本地工作目录路径，原始采样保持字节不变。另有 8 个预检进程、24 条操作，单独保留且不进入统计。源码审计比较构建前所有归档文件，两组原始归档相同，仅一个文件的一处 true/false 不同；实际加载的 ParameterAttribute 标记也逐进程验证。' if zh else 'All 1728 table operation records validate cell/header counts. Corresponding paired samples match native-output SHA256 and batch/component-update/edit counts. Fingerprints retain native element structure, attribute names/scalar values, text and markup; skip component parameters and framework IDs/reference captures; delegate values use their type. Delegate identity and browser behavior are not compared. Build logs redact only the local workspace path; raw samples retain their original bytes. 8 preflight processes / 24 operations are separate and excluded from statistics. Source audits compare all archived files before compilation: original archives match and only one true/false replacement differs. Actual loaded ParameterAttribute metadata is checked in every process.')
    limits=('Windows / .NET 10 / 一台机器；真实组件生命周期和渲染树 diff，但无浏览器 DOM、布局、JS、网络或 WASM。较高频率的小表交互、其他参数数量或真实未知属性捕获可能不同。这是实验性开关对照，不是可直接提交的兼容性方案；移除已有捕获 API 的兼容性需要另外评估。此前最终版相对 PR 前的 7.5% / 15.9–17.1% 功能成本包含不同工作，不能直接全归因于此开关，也不能把两轮比例相减来分解成本。' if zh else 'Windows / .NET 10 / one machine; real component lifecycle and render-tree diff, excluding browser DOM/layout, JS, network and WASM. Frequent small-table interactions, other parameter counts or actual unknown-attribute capture may differ. The disabled arm is an experimental control, not a compatibility-ready patch; removal of existing capture API requires separate review. Earlier final-versus-pre-PR feature costs of 7.5% / 15.9–17.1% involve different work and cannot all be attributed to this flag or decomposed by subtracting ratios between studies.')
    lines+=['', ('4 万格同数据更新的 12 对耗时比值变化范围为 -7.41% 至 +48.27%；+48.27% 的那一对按预案保留，没有剔除。该项毫秒列为 604.312 → 610.749 ms，但配对几何平均估计为 +5.92%，两者是不同统计量，波动需要如实保留。逐对数据见 [process-pairs.csv](results/windows-net10-capture-isolation-run5/process-pairs.csv)。' if zh else 'The 12 paired changes for default 40k same-data update range from -7.41% to +48.27%. The +48.27% pair is retained as planned. Millisecond medians are 604.312 → 610.749 ms, whereas the paired geometric-mean estimate is +5.92%; these are different statistics and the variability is retained. See [process-pairs.csv](results/windows-net10-capture-isolation-run5/process-pairs.csv).')]
    for heading,body in [('方法' if zh else 'Method',method),('场景与范围' if zh else 'Fixtures and scope',fixtures),('一致性与来源验证' if zh else 'Equivalence and provenance',validation),('限制' if zh else 'Limits',limits)]:lines+=['','## '+heading,'',body]
    lines+=['','## '+('公开证据' if zh else 'Public evidence'),'','- [Prospective protocol](protocols/capture-isolation.md) / [definition](protocols/capture-isolation.json) / [one-line library patch](experiments/capture-disabled.patch)','- [Raw records, manifest, source audits, build logs and checksums](results/windows-net10-capture-isolation-run5/)','- [All 44 table/helper estimates](results/windows-net10-capture-isolation-run5/summary.md) / [JSON](results/windows-net10-capture-isolation-run5/summary.json) / [samples CSV](results/windows-net10-capture-isolation-run5/samples.csv)','- [Validation](results/windows-net10-capture-isolation-run5/validation.json) / [source equivalence](results/windows-net10-capture-isolation-run5/source-equivalence.json) / [SHA256SUMS](results/windows-net10-capture-isolation-run5/SHA256SUMS)','- [Separate correctness preflight](results/capture-preflight/)','- [Earlier final vs pre-PR study](FINAL.md)','']
    (r/('CAPTURE.zh-CN.md' if zh else 'CAPTURE.md')).write_text('\n'.join(lines),encoding='utf-8')
